export async function getAuthorizationURL(
    app: JiraApp,
    read: IRead,
    user: IUser,
) {
    const { clientId } = await getCredentials(read);

    const baseURL = URLEnum.AUTHORIZE_URL;
    const audience = "api.atlassian.com";
    const redirectURL = await getCallbackURL(app);
    const responseType = "code";
    const prompt = "consent";

    const scope = [
        "read:jira-work",
        "write:jira-work",
        "read:jira-user",
        "read:me",
        "manage:jira-webhook",
        "offline_access",
    ].join(" ");

    const encodedScope = encodeURIComponent(scope);
    const encodedRedirect = encodeURIComponent(redirectURL);

    const state = user.id;

    const url =
        `${baseURL}?` +
        `audience=${audience}&` +
        `client_id=${clientId}&` +
        `scope=${encodedScope}&` +
        `redirect_uri=${encodedRedirect}&` +
        `state=${state}&` +
        `response_type=${responseType}&` +
        `prompt=${prompt}`;

    return url;
}

export interface IJiraAuthToken {
    accessToken: string;
    cloudID: string;
    refreshToken?: string;
    expiresIn?: number;
    scope?: string;
    tokenType?: string;
    createdAt: string;
    updatedAt: string;
}

