    app: JiraApp,
    read: IRead,
    modify: IModify,
    user: IUser,
    room: IRoom,
    persistence: IPersistence,
) {
    const url = await getAuthorizationURL(app, read, user);
    const blocks: LayoutBlock[] = [
        {
            type: "section",
            text: plainText("Click 👇 to Login with Jira"),
        },
        {
            type: "actions",
            elements: [
                buildButton({
                    appId: app.getID(),
                    text: "Login with Jira",
                    blockId: ElementEnum.LOGIN_BUTTON_BLOCK,
                    actionId: ElementEnum.LOGIN_BUTTON_ACTION,
                    url,
                    style: "primary",
                }),
            ],
        },
    ];
    await sendNotification(read, modify, user, room, "Login with Jira", blocks);
}

